let catalog;
try {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  const res = await fetch('http://192.168.86.237:8000/api/widgets/catalog', { signal: controller.signal });
  clearTimeout(timeout);
  if (!res.ok) throw new Error('status ' + res.status);
  catalog = await res.json();
  if (!Array.isArray(catalog) || catalog.length === 0) throw new Error('empty or non-array catalog');
} catch (e) {
  catalog = [
    { id: 'weather', description: 'Shows current weather conditions and temperature.' },
    { id: 'calendar', description: 'Shows upcoming calendar events.' },
    { id: 'spotify', description: 'Shows currently playing music.' },
  ];
}

return [{ json: { catalog } }];

