let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}

const catalogIds = new Set($('Catalog Ready').item.json.catalog.map(c => c.id));
let widgets = Array.isArray(parsed.widgets) ? parsed.widgets : [];

// Deterministic safety net regardless of what the model returned - drop
// any type not in the actual catalog, and clamp h to a sane range (1-2:
// normal or taller), matching calendar_event's implausibleDateError
// safety-net convention (and dashboard_control's own clampHeight, which
// applies the same rule for tool-driven changes). Array order IS display
// order - no separate position field needed.
widgets = widgets
  .filter(w => w && typeof w.type === 'string' && catalogIds.has(w.type))
  .map(w => ({ type: w.type, h: Math.max(1, Math.min(2, Math.round(w.h ?? 1))) }));

// Fallback: if the model produced nothing usable, include everything in
// the catalog's own order rather than showing a blank dashboard.
if (widgets.length === 0) {
  widgets = $('Catalog Ready').item.json.catalog.map(c => ({ type: c.id, h: 1 }));
}

return { json: { widgets, reasoning: typeof parsed.reasoning === 'string' ? parsed.reasoning : '' } };

const data = $('Fetch Dashboard Data').item.json; // { weather, calendar, spotify }
const widgets = $json.widgets.map(w => ({ type: w.type, h: w.h, data: data[w.type] ?? null }));
const updatedAt = new Date().toISOString();

return { json: { widgets, reasoning: $json.reasoning, updatedAt, widgetsJson: JSON.stringify(widgets) } };

let triggerSource;
try {
  $('From Webhook').item;
  triggerSource = 'webhook';
} catch (e) {
  triggerSource = 'schedule';
}
return { json: { ...$json, triggerSource } };
